describe('JavaScript Error Recovery', () => {
  beforeEach(() => {
    cy.visit('/app');
  });

  it('should recover gracefully after a JavaScript error and display error message', () => {
    // Intercept the initial page load
    cy.intercept('GET', '/api/data').as('initialData');
    cy.wait('@initialData');

    // Trigger the error by clicking a button that calls a faulty function
    cy.get('[data-testid="trigger-error-btn"]').click();

    // Verify the error state is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'An unexpected error occurred');

    // Verify the app is still functional after error
    cy.get('[data-testid="retry-btn"]').should('be.visible');
    cy.get('[data-testid="retry-btn"]').click();

    // Verify the app recovers and data is loaded again
    cy.get('[data-testid="error-message"]').should('not.exist');
    cy.get('[data-testid="data-display"]').should('be.visible');
    cy.get('[data-testid="data-display"]').should('contain', 'Data loaded successfully');
  });

  it('should handle multiple consecutive JavaScript errors and prevent infinite loops', () => {
    // Trigger the first error
    cy.get('[data-testid="trigger-error-btn"]').click();
    cy.get('[data-testid="error-message"]').should('be.visible');

    // Trigger a second error
    cy.get('[data-testid="trigger-error-btn"]').click();
    cy.get('[data-testid="error-message"]').should('be.visible');

    // Verify error counter is tracked
    cy.get('[data-testid="error-count"]').should('contain', '2');

    // Trigger a third error, which should trigger the max error limit
    cy.get('[data-testid="trigger-error-btn"]').click();

    // Verify the error state is now in a persistent/disabled mode
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Too many errors. Please refresh');

    // Verify retry button is disabled after max errors
    cy.get('[data-testid="retry-btn"]').should('be.disabled');

    // Verify user can still navigate away
    cy.get('[data-testid="nav-link-home"]').click();
    cy.get('[data-testid="nav-link-home"]').should('be.visible');
  });
});
